with valid as (select *, last_day(last_restock) as last_restock_month_end from inventory where last_restock >= date '2023-12-27'), with_windows as (select *, cume_dist() over w_ordered as quantity_cume_dist, lag(quantity, 1, 0) over w_ordered_2 as prev_quantity from valid window w_ordered as (partition by store_id order by quantity desc), w_ordered_2 as (order by last_restock, id)), base as (select id, store_id, product_id, quantity, last_restock, last_restock_month_end, quantity_cume_dist, quantity + prev_quantity as quantity_plus_prev_quantity from with_windows where quantity >= 214), deduped as (select *, row_number() over (partition by store_id order by last_restock_month_end desc nulls last, id) as dedup_rank from base qualify dedup_rank = 1) select id, product_id, quantity, last_restock, last_restock_month_end, quantity_cume_dist, quantity_plus_prev_quantity, dedup_rank from deduped order by product_id desc
